########## Equivalence and GCAs ##########

:CurrentBandMember a owl:Class ;
    rdfs:label "Current Band Member" ;
    rdfs:comment "A person who is currently a member of a band (no membershipEnd date)." ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            :Person
            [ a owl:Restriction ;
              owl:onProperty :isMemberOfMembership ;
              owl:someValuesFrom [
                  a owl:Class ;
                  owl:intersectionOf (
                      :BandMembership
                      [ a owl:Class ;
                        owl:complementOf [ a owl:Restriction ; owl:onProperty :membershipEnd ; owl:someValuesFrom xsd:dateTime ]
                      ]
                  )
              ]
            ]
        )
    ] .

########## Disjointness ##########

[ a owl:AllDisjointClasses ;
    owl:members (
        :Person
        :Band
        :Album
        :Song
        :Track
        :Performance
        :Instrument
        :Role
        :City
        :Region
        :Country
    )
] .

:Instrument owl:disjointWith :Role .
:Album owl:disjointWith :Performance .
:Song owl:disjointWith :Track .
:City owl:disjointWith :Region .
:Region owl:disjointWith :Country .

